module string_compression (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] s0, s1, s2, s3, s4, s5, s6, s7,\n    input [15:0] a, b,\n    input [3:0] n,\n    output reg [15:0] min_cost,\n    output reg done\n);\n\n    // State definition\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] CAPTURE  = 2'd1;\n    localparam [1:0] FINISH   = 2'd2;\n    \n    reg [1:0] state;\n    reg [7:0] s_reg [0:7];\n    reg [15:0] a_reg, b_reg;\n    reg [3:0] n_reg;\n    \n    // Internal computation tables\n    reg [3:0] lcp [0:8][0:8];\n    reg [3:0] maxL [0:7];\n    reg [15:0] dp [0:8];\n    \n    // Combinational logic\n    always @(*) begin\n        integer i, j, k;\n        integer L;\n        \n        // Initialize LCP table\n        for (i = 0; i <= 8; i = i + 1) begin\n            for (j = 0; j <= 8; j = j + 1) begin\n                lcp[i][j] = 4'd0;\n            end\n        end\n        \n        // Compute LCP table\n        for (j = 7; j >= 1; j = j - 1) begin\n            for (k = j-1; k >= 0; k = k - 1) begin\n                if (s_reg[k] == s_reg[j]) begin\n                    lcp[k][j] = lcp[k+1][j+1] + 4'd1;\n                end else begin\n                    lcp[k][j] = 4'd0;\n                end\n            end\n        end\n        \n        // Compute maxL array\n        for (j = 0; j < 8; j = j + 1) begin\n            maxL[j] = 4'd0;\n            for (k = 0; k < j; k = k + 1) begin\n                L = (lcp[k][j] < (j - k)) ? lcp[k][j] : (j - k);\n                if (L > maxL[j]) begin\n                    maxL[j] = L;\n                end\n            end\n        end\n        \n        // Compute DP\n        dp[0] = 16'd0;\n        for (i = 1; i <= 8; i = i + 1) begin\n            dp[i] = dp[i-1] + a_reg;\n            for (j = 0; j < i; j = j + 1) begin\n                if ((i - j) <= maxL[j]) begin\n                    if ((dp[j] + b_reg) < dp[i]) begin\n                        dp[i] = dp[j] + b_reg;\n                    end\n                end\n            end\n        end\n        \n        min_cost = dp[n_reg];\n    end\n    \n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        integer m;\n        \n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            // Initialize arrays\n            for (m = 0; m < 8; m = m + 1) begin\n                s_reg[m] <= 8'd0;\n            end\n            a_reg <= 16'd0;\n            b_reg <= 16'd0;\n            n_reg <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        s_reg[0] <= s0;\n                        s_reg[1] <= s1;\n                        s_reg[2] <= s2;\n                        s_reg[3] <= s3;\n                        s_reg[4] <= s4;\n                        s_reg[5] <= s5;\n                        s_reg[6] <= s6;\n                        s_reg[7] <= s7;\n                        a_reg <= a;\n                        b_reg <= b;\n                        n_reg <= n;\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule